import sys

def main():
    R = int(sys.stdin.readline().strip())

    # Upper half: 0 to R-1
    for i in range(R):
        if i == 0:
            print("*")
        else:
            left = ''.join(str(j) for j in range(1, i + 1))
            right = ''.join(str(j) for j in range(i - 1, 0, -1))
            print("*" + left + right + "*")

    # Lower half: R-2 down to 0
    for i in range(R - 2, -1, -1):
        if i == 0:
            print("*")
        else:
            left = ''.join(str(j) for j in range(1, i + 1))
            right = ''.join(str(j) for j in range(i - 1, 0, -1))
            print("*" + left + right + "*")

if __name__ == "__main__":
    main()
